import os, glob, numpy as np
for subj in sorted(glob.glob('/app/data/jm*')):
 if not os.path.isdir(subj): continue
 for ses in sorted(glob.glob(subj+'/*')):
  if not os.path.isdir(ses): continue
  vals=[]
  for pat in ['suite2p/plane*/F.npy','suite2p/plane*/Fneu.npy','suite2p/plane*/spks.npy','suite2p/plane*/iscell.npy','suite2p/plane*/ops.npy','move_deve/*.npy']:
   for f in glob.glob(ses+'/'+pat):
    try:
     x=np.load(f,allow_pickle=True)
     if x.shape==():
      d=x.item(); desc='dict '+str({k:d.get(k) for k in ['fs','nframes','neucoeff','baseline','win_baseline','sig_baseline','prctile_baseline'] if k in d})
     else:
      xf=x.astype(float) if x.dtype!=object else None
      desc=f'{x.shape} {x.dtype}' + (f' min={np.nanmin(xf):.3g} max={np.nanmax(xf):.3g} mean={np.nanmean(xf):.3g} nan={np.isnan(xf).sum()}' if xf is not None and xf.size else '')
